window.mountBeginnerLab=(el,kind)=>{if(kind==='none'){el.innerHTML='';return}const configs={temperature:['How certain do the choices look?',.2,2,.1,1,'Temperature'],learning:['Watch one weight learn',.01,.4,.01,.1,'Learning rate'],attention:['Mix two pieces of information',-4,4,.0001,Math.log(3),'Second key score'],cache:['How much history can the cache hold?',256,8192,256,1024,'Cached tokens'],context:['Pack a context deliberately',180,600,20,300,'Context budget'],similarity:['Direction versus length',.2,5,.1,1,'Document-vector length'],lora:['Change adapter capacity',8,128,8,32,'LoRA rank']};const c=configs[kind];if(!c)return;el.innerHTML=`<section class="experiment"><div class="eyebrow">PREDICT · MOVE THE SLIDER · EXPLAIN</div><h2>${c[0]}</h2><label>${c[5]} <output id="knob-value"></output><input id="knob" type="range" min="${c[1]}" max="${c[2]}" step="${c[3]}" value="${c[4]}"></label>${kind==='attention'?'<label class="check"><input id="mask" type="checkbox">Mask the second value as a future position</label>':''}<div id="lab-picture"></div><p id="lab-explanation" aria-live="polite"></p><button id="lab-reset">Reset example</button></section>`;const q=s=>el.querySelector(s),soft=s=>{let e=s.map(x=>Math.exp(x-Math.max(...s)));return e.map(x=>x/e.reduce((a,b)=>a+b,0))};function bars(labels,vals){return labels.map((label,i)=>`<div class="bar-row"><span>${label}</span><div class="track"><i style="width:${vals[i]*100}%"></i></div><b>${(vals[i]*100).toFixed(1)}%</b></div>`).join('')}function update(){let n=+q('#knob').value;q('#knob-value').textContent=n;let visual='',text='';if(kind==='temperature'){let p=soft([2/n,1/n,0]);visual=bars(['Reminder','Note','Question'],p);text='The underlying scores stay [2, 1, 0]. Temperature changes how strongly the leading choice is preferred. It does not add facts or fix the highest-scoring wrong choice.'}if(kind==='attention'){let w=q('#mask').checked?[1,0]:soft([0,n]);visual=bars(['Value A','Value B'],w);text=`A = [2, 0], B = [0, 4]. The mixture is [${(2*w[0]).toFixed(3)}, ${(4*w[1]).toFixed(3)}]. ${q('#mask').checked?'The future value contributes zero.':'Higher second-key scores move the mixture toward B.'}`}if(kind==='learning'){let w=1,rows=[];for(let i=0;i<6;i++){rows.push([i,w,(2*w-6)**2]);w-=n*4*(2*w-6)}visual='<div class="table-wrap"><table><tr><th>Step</th><th>Weight</th><th>Loss</th></tr>'+rows.map(r=>`<tr><td>${r[0]}</td><td>${r[1].toFixed(3)}</td><td>${r[2].toFixed(3)}</td></tr>`).join('')+'</table></div>';text='The best weight is 3. A small step moves slowly; an excessive step can overshoot and make loss grow. All values are calculated from the chapter’s equation.'}if(kind==='cache'){let mib=2*28*n*8*128*2/1024**2;visual=`<div class="big-number">${mib.toFixed(0)} <span>MiB of KV elements</span></div>`;text='One sequence, 28 layers, 8 KV heads, head width 128, and an illustrative 2 bytes per element. Weights, temporary buffers and allocation overhead are excluded. Double tokens, double this storage.'}if(kind==='context'){let available=n-80-100;visual=`<div class="big-number">${available}<span>tokens left for evidence</span></div>`;text=`This toy reserves 80 instruction tokens and 100 output tokens. At a ${n}-token total budget, evidence must fit in the remainder. This is budget arithmetic, not a tokenizer or proof of answer quality.`}if(kind==='similarity'){let dot=n/Math.sqrt(2);visual=`<div class="big-number">0.707<span>cosine similarity stays constant</span></div><p>Dot product: <strong>${dot.toFixed(3)}</strong></p>`;text='Query is [1, 0]. The document stays at 45 degrees while its length changes. Cosine compares direction; dot product also changes with magnitude.'}if(kind==='lora'){let count=n*2048;visual=`<div class="big-number">${count.toLocaleString()}<span>adapter parameters in one 1024 × 1024 layer</span></div>`;text=`Full layer: 1,048,576 weights. Adapter: ${(100*count/1048576).toFixed(2)}% of that count. At alpha 64, standard scale = ${(64/n).toFixed(2)}; rsLoRA scale = ${(64/Math.sqrt(n)).toFixed(2)}. This does not estimate total training memory.`}q('#lab-picture').innerHTML=visual;q('#lab-explanation').textContent=text}q('#knob').oninput=update;if(q('#mask'))q('#mask').onchange=update;q('#lab-reset').onclick=()=>{q('#knob').value=c[4];if(q('#mask'))q('#mask').checked=false;update()};update()};
var originalBeginnerLab=window.mountBeginnerLab;window.mountBeginnerLab=function(el,kind){if(kind!=='transformer')return originalBeginnerLab(el,kind);const stages=[['Token IDs','[2, 8]','Two requests, eight token positions each. Each integer identifies one vocabulary entry. No learned features have been looked up yet.'],['Embeddings','[2, 8, 32]','Each token selects a row of 32 learned numbers. The batch and sequence axes stay the same. Position information will make order visible.'],['Attention','[2, 8, 32]','Queries compare with allowed keys; the resulting weights mix values. Earlier positions cannot inspect the future. Heads are combined back to width 32.'],['Residual + MLP','[2, 8, 32]','Add the attention update, then apply a normalized feed-forward transformation and add that update. Blocks repeat; the working representation keeps its shape.'],['Vocabulary scores','[2, 8, 100]','A final projection creates 100 scores per position, one for each token in the toy vocabulary. These scores are logits, not yet probabilities.'],['Next token','[2, 1]','For generation, use the final position’s scores to choose one next token for each sequence. Append it and repeat. Training instead scores many shifted targets.']];let i=0;el.innerHTML='<section class="experiment"><div class="eyebrow">FOLLOW ONE FORWARD PASS</div><h2>A token’s journey</h2><div class="transformer-steps" style="display:flex;gap:6px;flex-wrap:wrap"></div><div class="big-number" id="tensor-shape"></div><p id="tensor-story"></p><button id="tensor-next">Next transformation →</button></section>';function draw(){el.querySelector('.transformer-steps').innerHTML=stages.map((s,n)=>'<button data-step="'+n+'" aria-pressed="'+(i===n)+'" style="margin:4px 0;'+(i===n?'background:#abc9ff;color:#142239':'')+'">'+(n+1)+'. '+s[0]+'</button>').join('');el.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{i=+b.dataset.step;draw()});el.querySelector('#tensor-shape').textContent=stages[i][1];el.querySelector('#tensor-story').textContent=stages[i][2];el.querySelector('#tensor-next').textContent=i===5?'Start again ↺':'Next transformation →'}el.querySelector('#tensor-next').onclick=()=>{i=(i+1)%stages.length;draw()};draw()};

;

