  "trie": "https://www.hellointerview.com/learn/code/trie/implement-trie",
  "valid-parentheses": "https://www.hellointerview.com/learn/code/stack/valid-parentheses",
  "daily-temperatures": "https://www.hellointerview.com/learn/code/stack/daily-temperatures",
